// The provider's answer to a refund that is still requested. A failed
// answer ends the refund; succeeded / uncertain wait for the posting / a
// person.
func (q *Queries) SetRefundProviderAnswer(ctx context.Context, arg SetRefundProviderAnswerParams) (int64, error) {
	result, err := q.db.Exec(ctx, setRefundProviderAnswer,
		arg.ProviderStatus,
		arg.ProviderRefundID,
		arg.FailureReason,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

